     public InputStream getStream(String objectKey) {
         Path p = resolve(objectKey);
         if (!Files.isRegularFile(p)) {
             return null;
         }
         try {
             return new ByteArrayInputStream(Files.readAllBytes(p));
         } catch (IOException e) {
             throw new UncheckedIOException("storage read failed", e);
         }
     }

